import React from 'react';
import { ChevronRight, Plus, Users } from 'lucide-react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import '../styles/cards.css';

export default function GroupCard({ group, onExpenseClick }) {
  const navigate = useNavigate();
  
  // Safe data extraction
  const memberCount = group.members?.length || 0;
  const totalExpenses = group.expenses?.reduce((sum, e) => sum + e.amount, 0) || 0;
  const visibleMembers = group.members?.slice(0, 3) || [];

  // Format currency professionally
  const formatCurrency = (val) => 
    new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);

  return (
    <motion.div
      className="group-card"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ y: -5 }}
      transition={{ duration: 0.2 }}
    >
      <div className="card-header">
        <div className="card-icon">
          <Users size={20} color="var(--accent)" />
        </div>
        <div className="card-title-section">
          <h3>{group.name}</h3>
          <p className="card-meta">{memberCount} {memberCount === 1 ? 'Member' : 'Members'}</p>
        </div>
      </div>

      <div className="card-stats">
        <div className="stat-item">
          <span className="stat-label">Total Spent</span>
          <span className="stat-value">{formatCurrency(totalExpenses)}</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">Your Share</span>
          <span className="stat-value" style={{ opacity: 0.5 }}>$0.00</span>
        </div>
      </div>

      <div className="card-members">
        <div className="members-preview">
           {/* Display +More first because CSS flex-direction: row-reverse handles the order */}
          {memberCount > 3 && (
            <div className="member-mini more">
              +{memberCount - 3}
            </div>
          )}
          {visibleMembers.map((member, i) => {
            const person = member.user || member;
            const initials = person.name?.charAt(0).toUpperCase() || '?';
            
            return (
              <div
                key={person._id || `member-${i}`}
                className="member-mini"
                title={person.name}
              >
                {initials}
              </div>
            );
          })}
        </div>
      </div>

      <div className="card-actions">
        <button
          className="btn-action"
          onClick={(e) => {
            e.stopPropagation();
            onExpenseClick();
          }}
        >
          <Plus size={16} style={{ marginRight: '6px' }} />
          Expense
        </button>
        <button
          className="btn-action secondary"
          onClick={() => navigate(`/group/${group._id}`)}
          aria-label="View Details"
        >
          <ChevronRight size={18} />
        </button>
      </div>
    </motion.div>
  );
}
